SHIPPING_FEES = {'standard': 5}

def validate_order(order):
    if order['qty'] <= 0:
        raise ValueError('Invalid quantity')
    if order['shipping'] not in SHIPPING_FEES:
        raise ValueError('Unsupported shipping')

def order_total(order):
    return order['qty'] * order['price'] + SHIPPING_FEES[order['shipping']]
